const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Rectangle([-74.3, 40.5, -73.7, 40.9]); // NYC bounding box
  const date = '2002-08-14';
  const startDate = ee.Date(date).advance(-7, 'day');
  const endDate = ee.Date(date).advance(7, 'day');

  // Helper function to mask clouds and shadows for Landsat 7
  function maskL7sr(image) {
    const qa = image.select('QA_PIXEL');
    const cloudShadowBitMask = 1 << 3;
    const cloudsBitMask = 1 << 4;
    const waterBitMask = 1 << 7;

    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
                 .and(qa.bitwiseAnd(waterBitMask).eq(0)); // non-water
    return image.updateMask(mask);
  }

  // Helper to get and process image from a collection
  async function getProcessedImage(collectionName) {
    let col = ee.ImageCollection(collectionName)
                .filterBounds(nyc)
                .filterDate(startDate, endDate)
                .map(maskL7sr);

    const size = col.size().getInfo();
    if (size === 0) return null;

    // Get median composite to reduce noise
    let image = col.median().clip(nyc);

    // Compute NDVI
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');

    // Get surface temperature in Celsius (ST_B10 is in Kelvin)
    const temp = image.select('ST_B10').multiply(0.00341802).add(149.0) // to Kelvin
                   .subtract(273.15).rename('LST_C'); // to Celsius

    // Combine bands
    image = image.addBands([ndvi, temp]);

    // Mask out extreme values (optional, but helps with outliers)
    image = image.updateMask(
      image.select('NDVI').gt(-1).and(image.select('NDVI').lt(1))
        .and(image.select('LST_C').gt(-50)).and(image.select('LST_C').lt(60))
    );

    return image;
  }

  // 2. Data Acquisition & Check
  let image = null;
  let source = '';

  // Try Landsat 7 first
  image = await getProcessedImage('LANDSAT/LE07/C02/T1_L2');
  if (image) {
    source = 'Landsat7';
  } else {
    // Try Landsat 5 as fallback
    image = await getProcessedImage('LANDSAT/LT05/C02/T1_L2');
    if (image) {
      source = 'Landsat5';
    }
  }

  if (!image) {
    console.log(`No images found for ${date} ±7 days.`);
    console.log('<answer>C1</answer>');
    return;
  }

  console.log(`Using ${source}, date range: ${startDate.format('YYYY-MM-dd').getInfo()} to ${endDate.format('YYYY-MM-dd').getInfo()}`);

  // 3. Check valid pixels
  const count = image.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: nyc,
    scale: 1000,
    maxPixels: 1e9,
  }).get('NDVI').getInfo();

  if (count === 0) {
    console.log(`Valid pixels: 0`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate correlation between NDVI and temperature
  const covar = image.select(['NDVI', 'LST_C']).reduceRegion({
    reducer: ee.Reducer.covariance(),
    geometry: nyc,
    scale: 1000,
    maxPixels: 1e9,
  }).getInfo();

  const covMatrix = covar['array'];
  const ndviVar = covMatrix[0][0];
  const lstVar = covMatrix[1][1];
  const covariance = covMatrix[0][1];

  // Avoid division by zero
  let correlation = null;
  if (ndviVar > 0 && lstVar > 0) {
    correlation = covariance / Math.sqrt(ndviVar * lstVar);
  }

  console.log(`Valid pixels: ${count}`);
  console.log(`Correlation (NDVI vs LST): ${correlation !== null ? correlation.toFixed(3) : 'NaN'}`);

  // 5. Validation & Final Answer
  if (correlation === null || isNaN(correlation) || Math.abs(correlation) > 1) {
    console.log('<answer>C3</answer>');
  } else if (correlation < 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
